<?php
/**
 * The 99 Names of Allah (Asma ul-Husna).
 *
 * Reflections drawn from al-Ghazali's "Al-Maqsad al-Asna" and Ibn Qayyim's
 * "Madarij al-Salikin", condensed to ~40 words each — long enough to spark
 * contemplation, short enough to be sat with in 30-60 seconds.
 *
 * The list follows the most commonly cited ordering attributed to Tirmidhi 3507.
 * Allah ﷻ knows best — these are aids to contemplation, not boundaries on His mercy.
 *
 * @package LoveAllah
 */

if ( ! defined( 'ABSPATH' ) ) exit;

function la_asma_ul_husna() : array {
	return [
		[ 'n' => 'Ar-Rahman',      'ar' => 'الرَّحْمٰن',     'meaning' => 'The Most Merciful',                       'reflection' => 'His mercy encompasses all things. The same mercy that flows to the disbeliever in Mecca flows to the believer at tahajjud. The air in your lungs, the heart still beating — these are not earned. They are Ar-Rahman.' ],
		[ 'n' => 'Ar-Raheem',      'ar' => 'الرَّحِيم',      'meaning' => 'The Especially Merciful',                 'reflection' => 'Ar-Rahman to all of creation; Ar-Raheem specifically to the believers. The intimate mercy — the prayer answered, the tear wiped, the grief soothed in the quiet of the night. He sees yours.' ],
		[ 'n' => 'Al-Malik',       'ar' => 'الْمَلِك',       'meaning' => 'The King, the Sovereign',                 'reflection' => 'No throne rivals His. No decree precedes His. The Sovereign of every atom, every breath, every kingdom that ever rose and fell. Bow to the King — He has not asked you to bow to lesser kings.' ],
		[ 'n' => 'Al-Quddus',      'ar' => 'الْقُدُّوس',     'meaning' => 'The Holy, the Pure',                      'reflection' => 'Free from every defect, every flaw, every limitation of the created. When you contemplate Allah, drop the mental images — He is beyond what you can picture. Al-Quddus.' ],
		[ 'n' => 'As-Salam',       'ar' => 'السَّلَام',      'meaning' => 'The Peace, the Source of Peace',          'reflection' => 'Peace is not the absence of trouble — it is His name reflected in the heart that knows Him. The greeting of the believers in Jannah is from this name. Salam.' ],
		[ 'n' => 'Al-Mu\'min',     'ar' => 'الْمُؤْمِن',     'meaning' => 'The Guarantor of Faith and Safety',        'reflection' => 'He keeps His promise. He makes the believer feel safe. Every fear you carry — about death, about loved ones, about your standing with Him — meets Al-Mu\'min at the door.' ],
		[ 'n' => 'Al-Muhaymin',    'ar' => 'الْمُهَيْمِن',    'meaning' => 'The Overseer, the Guardian',              'reflection' => 'He sees every action. Not as surveillance — as care. The Guardian over creation watches you the way a shepherd watches the flock that has wandered into the dark.' ],
		[ 'n' => 'Al-Aziz',        'ar' => 'الْعَزِيز',      'meaning' => 'The Almighty, the Invincible',            'reflection' => 'Honour without limit, might without compromise. The Aziz cannot be overcome — and the believer who relies on Him cannot be ultimately defeated, no matter what loss appears.' ],
		[ 'n' => 'Al-Jabbar',      'ar' => 'الْجَبَّار',     'meaning' => 'The Compeller, the Restorer',             'reflection' => 'The one who mends what is broken — hearts, bones, futures. His compelling is not tyranny; it is the doctor setting the fracture. Painful for a moment, the only path to healing.' ],
		[ 'n' => 'Al-Mutakabbir',  'ar' => 'الْمُتَكَبِّر',   'meaning' => 'The Greatest, the Supremely Exalted',     'reflection' => 'Greatness belongs to Him alone. When humans claim it, it is theft. Sit with this — the pride you carry today, return it to its rightful owner.' ],

		[ 'n' => 'Al-Khaliq',      'ar' => 'الْخَالِق',      'meaning' => 'The Creator',                             'reflection' => 'He brought you into being from non-being. Before you were anything, you were known to Al-Khaliq. He chose your face, your time, your trial. Nothing about you is accident.' ],
		[ 'n' => 'Al-Bari',        'ar' => 'الْبَارِئ',      'meaning' => 'The Originator',                          'reflection' => 'Without precedent. Without blueprint. He made the first of every kind from nothing — and He can make a new beginning for you from whatever ruin you are sitting in.' ],
		[ 'n' => 'Al-Musawwir',    'ar' => 'الْمُصَوِّر',    'meaning' => 'The Fashioner of Forms',                  'reflection' => 'Every face, every fingerprint, every leaf — formed by Him with intention. He shaped you not at random but with care. Your reflection in the mirror is His work.' ],
		[ 'n' => 'Al-Ghaffar',     'ar' => 'الْغَفَّار',     'meaning' => 'The Constant Forgiver',                   'reflection' => 'Repeatedly forgives, again and again, however many times you return. Al-Ghaffar does not grow tired of your repentance. The shame you carry is heavier than the sin — and He removes both.' ],
		[ 'n' => 'Al-Qahhar',      'ar' => 'الْقَهَّار',     'meaning' => 'The Dominant',                            'reflection' => 'Every empire bows. Every tyrant, eventually, falls. The Qahhar will not let injustice run forever — even when patience is required, the end is certain.' ],
		[ 'n' => 'Al-Wahhab',      'ar' => 'الْوَهَّاب',     'meaning' => 'The Bestower of Gifts',                   'reflection' => 'He gives without you asking. Without you deserving. The lungs that fill, the eyes that see, the people who love you — all gifts from Al-Wahhab. What have you thanked Him for today?' ],
		[ 'n' => 'Ar-Razzaq',      'ar' => 'الرَّزَّاق',     'meaning' => 'The Provider',                            'reflection' => 'Your sustenance is written. The rizq does not flow from the boss, the contract, or the bank — it flows through them, from Ar-Razzaq. He has not forgotten you. He never has.' ],
		[ 'n' => 'Al-Fattah',      'ar' => 'الْفَتَّاح',     'meaning' => 'The Opener',                              'reflection' => 'Doors close. Plans collapse. Then a door you never noticed opens, and you see Al-Fattah behind it. He opens what no one can shut — including the doors of the heart.' ],
		[ 'n' => 'Al-\'Alim',      'ar' => 'الْعَلِيم',      'meaning' => 'The All-Knowing',                         'reflection' => 'He knows what you have not said aloud. The reason you cried last night, the longing you would not admit even to yourself. Al-\'Alim already knows. Speak to Him without translation.' ],
		[ 'n' => 'Al-Qabid',       'ar' => 'الْقَابِض',      'meaning' => 'The Constrictor',                         'reflection' => 'He withholds — sometimes provision, sometimes ease, sometimes joy. Not from cruelty, but from love. What is withheld now is being kept for a better moment. Trust the Qabid.' ],

		[ 'n' => 'Al-Basit',       'ar' => 'الْبَاسِط',      'meaning' => 'The Expander',                            'reflection' => 'After constriction, expansion. The chest opens. The road widens. Al-Basit gives breathing room when you thought you had none left. Don\'t panic at the squeeze — the expansion follows.' ],
		[ 'n' => 'Al-Khafid',      'ar' => 'الْخَافِض',      'meaning' => 'The Abaser',                              'reflection' => 'He brings down the proud. He humbles the one who oppresses. When you watch the powerful fall in this world — Al-Khafid is at work, on time.' ],
		[ 'n' => 'Ar-Rafi\'',      'ar' => 'الرَّافِع',      'meaning' => 'The Exalter',                             'reflection' => 'And He lifts up the lowly. The one nobody noticed becomes the one history records. Status with Him is the only status that lasts. Ar-Rafi\' raises the heart of the broken.' ],
		[ 'n' => 'Al-Mu\'izz',     'ar' => 'الْمُعِزّ',      'meaning' => 'The Giver of Honour',                     'reflection' => 'Honour from Him cannot be taken by any man. Honour from men can be taken in a sentence. Seek the honour that holds — Al-Mu\'izz gives it to His humble servants.' ],
		[ 'n' => 'Al-Mudhill',     'ar' => 'الْمُذِلّ',      'meaning' => 'The Giver of Dishonour',                  'reflection' => 'He strips the honour of those who chose pride over truth. A solemn name — and a warning. Whatever pride you are carrying now, set it down before He sets it down for you.' ],
		[ 'n' => 'As-Sami\'',      'ar' => 'السَّمِيع',      'meaning' => 'The All-Hearing',                         'reflection' => 'Every whisper, every cry, every du\'a — heard. He hears the prayer of the ant. He hears yours. Even the ones you make without words. Especially those.' ],
		[ 'n' => 'Al-Basir',       'ar' => 'الْبَصِير',      'meaning' => 'The All-Seeing',                          'reflection' => 'He sees the act, He sees the intention, He sees what shaped the intention. Nothing is hidden — and that is mercy, because He alone can judge you justly.' ],
		[ 'n' => 'Al-Hakam',       'ar' => 'الْحَكَم',       'meaning' => 'The Judge',                               'reflection' => 'The final court. Every injustice you have suffered, every truth you could not prove — Al-Hakam will settle it. You will not be denied that day.' ],
		[ 'n' => 'Al-\'Adl',       'ar' => 'الْعَدْل',       'meaning' => 'The Just',                                'reflection' => 'Justice without bias, without bribe, without favouritism. The one whose injustice was overlooked — Al-\'Adl saw it. Their day comes.' ],
		[ 'n' => 'Al-Latif',       'ar' => 'اللَّطِيف',      'meaning' => 'The Subtle, the Gentle',                  'reflection' => 'He is gentle in His care for you — moving things behind the scenes so softly you only notice years later. The "coincidences" that saved you. The chance meeting that changed your life. Al-Latif.' ],

		[ 'n' => 'Al-Khabir',      'ar' => 'الْخَبِير',      'meaning' => 'The Acquainted, the All-Aware',           'reflection' => 'He knows the inside of every situation. The motive behind the smile. The fear behind the anger. Al-Khabir knows what you cannot articulate — and answers it.' ],
		[ 'n' => 'Al-Halim',       'ar' => 'الْحَلِيم',      'meaning' => 'The Forbearing',                          'reflection' => 'He could punish immediately. He does not. The space between the sin and the response is His Hilm — giving you time to come back. Don\'t waste it.' ],
		[ 'n' => 'Al-\'Adheem',    'ar' => 'الْعَظِيم',      'meaning' => 'The Magnificent',                         'reflection' => 'Vast beyond measure. The mountains, the oceans, the galaxies — these are not big to Him. He is bigger. And He bends to listen to your du\'a.' ],
		[ 'n' => 'Al-Ghafoor',     'ar' => 'الْغَفُور',      'meaning' => 'The All-Forgiving',                       'reflection' => 'Covers the sin entirely. Not just overlooks — erases. The one who repents sincerely meets Al-Ghafoor on a clean slate. Even the angels are no longer told.' ],
		[ 'n' => 'Ash-Shakoor',    'ar' => 'الشَّكُور',      'meaning' => 'The Appreciative',                        'reflection' => 'He multiplies the small good you do. A coin given quietly becomes a mountain on the scales. A word of dhikr returns a hundred. Ash-Shakoor never lets a sincere deed go unnoticed.' ],
		[ 'n' => 'Al-\'Aliyy',     'ar' => 'الْعَلِيّ',      'meaning' => 'The Most High',                           'reflection' => 'Above every height the mind can imagine. The arsh sits below Him. There is no "up" beyond Him. When you raise your hands in du\'a, you raise them toward Al-\'Aliyy.' ],
		[ 'n' => 'Al-Kabir',       'ar' => 'الْكَبِير',      'meaning' => 'The Greatest',                            'reflection' => 'The Greatest. When we say "Allahu Akbar" in our prayer, we are saying: there is nothing greater than this moment with You. Not the meeting, not the deadline, not the worry. Allah is greater.' ],
		[ 'n' => 'Al-Hafidh',      'ar' => 'الْحَفِيظ',      'meaning' => 'The Preserver',                           'reflection' => 'He preserves what matters. The Quran kept word-for-word for 1400 years. The good deed you forgot — kept. Al-Hafidh forgets nothing of what should be remembered.' ],
		[ 'n' => 'Al-Muqit',       'ar' => 'الْمُقِيت',      'meaning' => 'The Nourisher',                           'reflection' => 'He provides the food of bodies and the food of souls. Iman is rizq. Khushu in prayer is rizq. Beg Al-Muqit for the rizq that lasts.' ],
		[ 'n' => 'Al-Hasib',       'ar' => 'الْحَسِيب',      'meaning' => 'The Reckoner',                            'reflection' => 'The one who keeps account. Every kindness you did, every cruelty you suffered, every coin spent in His way — recorded. Al-Hasib will not lose a single entry.' ],

		[ 'n' => 'Al-Jalil',       'ar' => 'الْجَلِيل',      'meaning' => 'The Majestic',                            'reflection' => 'Majesty that demands awe. Stand before Him in prayer — properly, attentively, knowing whose presence you are in. Al-Jalil is not casual. Don\'t be casual with Him.' ],
		[ 'n' => 'Al-Karim',       'ar' => 'الْكَرِيم',      'meaning' => 'The Generous',                            'reflection' => 'Gives even when asked rudely. Gives even when not asked. The Karim does not count what He gave you — He keeps giving. What does that ask of you toward others?' ],
		[ 'n' => 'Ar-Raqib',       'ar' => 'الرَّقِيب',      'meaning' => 'The Watchful',                            'reflection' => 'Watching with care, not surveillance. The way a mother watches her child sleep. Ar-Raqib is awake while you sleep, present while you forget. You are never alone.' ],
		[ 'n' => 'Al-Mujib',       'ar' => 'الْمُجِيب',      'meaning' => 'The Responsive',                          'reflection' => 'He answers du\'a. Sometimes with yes. Sometimes with not yet. Sometimes with something better than you asked for. Al-Mujib never ignores. Keep asking.' ],
		[ 'n' => 'Al-Wasi\'',      'ar' => 'الْوَاسِع',      'meaning' => 'The All-Encompassing',                    'reflection' => 'His mercy is wider than your sin. His knowledge wider than your confusion. There is no question you can ask that He has not already encompassed.' ],
		[ 'n' => 'Al-Hakim',       'ar' => 'الْحَكِيم',      'meaning' => 'The Wise',                                'reflection' => 'Every decree carries wisdom you may not see for years. The job you didn\'t get. The marriage that didn\'t happen. Al-Hakim arranged it — the wisdom will surface in time.' ],
		[ 'n' => 'Al-Wadood',      'ar' => 'الْوَدُود',      'meaning' => 'The Loving, the Affectionate',            'reflection' => 'He loves you. Not tolerates — loves. Despite what you know about yourself, Al-Wadood loves the believer who turns to Him. Believe this enough to act on it.' ],
		[ 'n' => 'Al-Majid',       'ar' => 'الْمَجِيد',      'meaning' => 'The Glorious',                            'reflection' => 'Glory belongs to Him entirely. Whatever glory creation carries is borrowed. Return it to the source — and find that the heart settles when the borrowed glory is given back.' ],
		[ 'n' => 'Al-Ba\'ith',     'ar' => 'الْبَاعِث',      'meaning' => 'The Resurrector',                         'reflection' => 'He raised the dead before — Uzayr, the slain of Bani Israil. He will raise everyone. Al-Ba\'ith. The one who buries you knows Who is calling you back up.' ],
		[ 'n' => 'Ash-Shahid',     'ar' => 'الشَّهِيد',      'meaning' => 'The Witness',                             'reflection' => 'He sees what no one else saw. The good deed done in private, the cruelty done behind closed doors. Ash-Shahid testifies on the Day — and His testimony is the only one that matters.' ],

		[ 'n' => 'Al-Haqq',        'ar' => 'الْحَقّ',        'meaning' => 'The Truth',                               'reflection' => 'The Real. Everything else is fleeting — appears solid, then vanishes. Al-Haqq remains. Build your life on what is real, not what looks real.' ],
		[ 'n' => 'Al-Wakil',       'ar' => 'الْوَكِيل',      'meaning' => 'The Trustee, the Disposer',               'reflection' => 'Hand it to Him. The thing you cannot fix. The future you cannot control. Hasbunallah wa ni\'mal-Wakil — sufficient for us is Allah, and the best of trustees.' ],
		[ 'n' => 'Al-Qawiyy',      'ar' => 'الْقَوِيّ',      'meaning' => 'The Strong',                              'reflection' => 'Strength that does not weaken. When your strength runs out — and it will — Al-Qawiyy is the strength you borrow from. Lean on Him.' ],
		[ 'n' => 'Al-Matin',       'ar' => 'الْمَتِين',      'meaning' => 'The Firm',                                'reflection' => 'Unshakeable. The decree that no force can overturn. The promise no betrayal can void. Al-Matin holds when everything else crumbles.' ],
		[ 'n' => 'Al-Waliyy',      'ar' => 'الْوَلِيّ',      'meaning' => 'The Protecting Friend',                   'reflection' => 'A friend who never leaves. Who does not need anything from you. Who is on your side even when you are not on your own. Al-Waliyy of the believers — that is you, if you turn to Him.' ],
		[ 'n' => 'Al-Hamid',       'ar' => 'الْحَمِيد',      'meaning' => 'The Praiseworthy',                        'reflection' => 'Every praise spoken in every language traces back to Al-Hamid. Even praise of others is, ultimately, praise of what He shaped. Alhamdulillahi rabbil-\'alameen.' ],
		[ 'n' => 'Al-Muhsi',       'ar' => 'الْمُحْصِي',      'meaning' => 'The Accounter',                           'reflection' => 'He counts the grains of sand and the breaths you took today. Nothing too small to notice. Al-Muhsi notices the seemingly insignificant good you did — counted, kept, valued.' ],
		[ 'n' => 'Al-Mubdi\'',     'ar' => 'الْمُبْدِئ',      'meaning' => 'The Originator (Beginner)',               'reflection' => 'He started everything. Without precedent. Time itself is one of His creations. When you feel you cannot start over, remember: Al-Mubdi\' specializes in beginnings.' ],
		[ 'n' => 'Al-Mu\'id',      'ar' => 'الْمُعِيد',      'meaning' => 'The Restorer',                            'reflection' => 'He brings back. The one who lapsed — restored. The deeds that felt lost — returned. Al-Mu\'id is why repentance works, why the Day of Judgement happens, why nothing is finally lost.' ],
		[ 'n' => 'Al-Muhyi',       'ar' => 'الْمُحْيِي',      'meaning' => 'The Giver of Life',                       'reflection' => 'He gives life to the dead earth with rain, life to the dead heart with the Quran. The morning you wake up after a night of grief — Al-Muhyi just made you again.' ],

		[ 'n' => 'Al-Mumit',       'ar' => 'الْمُمِيت',      'meaning' => 'The Bringer of Death',                    'reflection' => 'He decides when. Not the doctor, not the disease, not the road. The appointed time is with Al-Mumit alone. Live like the appointment is closer than you think.' ],
		[ 'n' => 'Al-Hayy',        'ar' => 'الْحَيّ',        'meaning' => 'The Ever-Living',                         'reflection' => 'Always alive, never absent, never asleep. Every other source of help can be unavailable. Al-Hayy is awake right now, hearing you.' ],
		[ 'n' => 'Al-Qayyum',      'ar' => 'الْقَيُّوم',      'meaning' => 'The Self-Subsisting Sustainer',          'reflection' => 'He needs no one to maintain Him. Everything else needs Him to maintain it. The atoms hold together because of Al-Qayyum. The verse 2:255 calls Him this — let it sink in.' ],
		[ 'n' => 'Al-Wajid',       'ar' => 'الْوَاجِد',      'meaning' => 'The Finder',                              'reflection' => 'Nothing is lost to Him. The friend you cannot find — found. The lost prayer you forgot — found. The you that you were before life damaged you — found, by Al-Wajid.' ],
		[ 'n' => 'Al-Majid',       'ar' => 'الْمَاجِد',      'meaning' => 'The Noble',                               'reflection' => 'Nobility of essence. He does not require anyone to vouch for Him. The believer who knows Al-Majid does not need the world\'s approval — they have it from the only source that lasts.' ],
		[ 'n' => 'Al-Wahid',       'ar' => 'الْوَاحِد',      'meaning' => 'The One',                                 'reflection' => 'One. Not the first of many — the only One. La sharika lah — no partner. When the heart finally accepts this, every other "god" (job, status, fear) loses its grip.' ],
		[ 'n' => 'Al-Ahad',        'ar' => 'الْأَحَد',        'meaning' => 'The Unique',                              'reflection' => 'Indivisible. The complete monotheism of Surah al-Ikhlas. No image fits, no analogy holds. Al-Ahad — and the heart finds rest in the simplicity of Him alone.' ],
		[ 'n' => 'As-Samad',       'ar' => 'الصَّمَد',      'meaning' => 'The Eternal Refuge',                      'reflection' => 'The one everyone turns to. Without need of food, sleep, sustenance — but every need flows back to Him. As-Samad. The one the universe leans on; lean on Him too.' ],
		[ 'n' => 'Al-Qadir',       'ar' => 'الْقَادِر',      'meaning' => 'The Capable',                             'reflection' => 'Capable of anything He wills. The thing you think is impossible is, for Al-Qadir, the same as easy. Don\'t shrink your du\'a to fit your imagination.' ],
		[ 'n' => 'Al-Muqtadir',    'ar' => 'الْمُقْتَدِر',    'meaning' => 'The Powerful',                            'reflection' => 'Possessor of complete power. He executes what He wills. Pharaoh\'s armies, Nuh\'s flood, Musa\'s sea — Al-Muqtadir. The same power is on your side when you turn to Him.' ],

		[ 'n' => 'Al-Muqaddim',    'ar' => 'الْمُقَدِّم',     'meaning' => 'The Expediter',                           'reflection' => 'He brings forward what He wills. Births, marriages, moments of mercy — at the time He chooses, not before. The waiting is part of the plan.' ],
		[ 'n' => 'Al-Mu\'akhkhir', 'ar' => 'الْمُؤَخِّر',     'meaning' => 'The Delayer',                             'reflection' => 'He delays what He wills. The answer that did not come yet — not refused. Held. Al-Mu\'akhkhir is choosing the right moment for what you asked for.' ],
		[ 'n' => 'Al-Awwal',       'ar' => 'الْأَوَّل',       'meaning' => 'The First',                               'reflection' => 'Before time, before space, before anything that began. He alone is uncreated. When you trace your existence back far enough — Al-Awwal is where you stop.' ],
		[ 'n' => 'Al-Akhir',       'ar' => 'الْآخِر',         'meaning' => 'The Last',                                'reflection' => 'After everything ends, He remains. The stars burn out. The earth folds away. Al-Akhir is still there — and the believer who held to Him is still with Him.' ],
		[ 'n' => 'Adh-Dhahir',     'ar' => 'الظَّاهِر',      'meaning' => 'The Manifest',                            'reflection' => 'Apparent through the signs — every leaf, every breath, every dawn. If you cannot see Him, you are not looking. He is hiding in plain sight, on purpose, because the looking is part of the worship.' ],
		[ 'n' => 'Al-Batin',       'ar' => 'الْبَاطِن',      'meaning' => 'The Hidden',                              'reflection' => 'And hidden from the eyes. His essence is not seen in this life — only His effects. Al-Batin. The believer learns to know Him through what He does, not what He looks like.' ],
		[ 'n' => 'Al-Wali',        'ar' => 'الْوَالِي',      'meaning' => 'The Governor',                            'reflection' => 'Governing all affairs. From the path of an ant to the rise of nations — Al-Wali manages it. Your tiny concerns are not too small for His attention.' ],
		[ 'n' => 'Al-Muta\'ali',   'ar' => 'الْمُتَعَالِي',   'meaning' => 'The Self-Exalted',                        'reflection' => 'Exalted above every limitation the human mind tries to place on Him. Whenever your image of God shrinks Him to manageable size — Al-Muta\'ali corrects you.' ],
		[ 'n' => 'Al-Barr',        'ar' => 'الْبَرّ',         'meaning' => 'The Source of Goodness',                  'reflection' => 'Every good in existence flows from Al-Barr. The kindness you received was His. The kindness you gave — also from Him. Goodness is one stream with one source.' ],
		[ 'n' => 'At-Tawwab',      'ar' => 'التَّوَّاب',      'meaning' => 'The Ever-Accepting of Repentance',        'reflection' => 'He turns toward the one who turns toward Him. Even if you have turned away a thousand times — the thousand-and-first return is welcomed. At-Tawwab. The door does not close.' ],

		[ 'n' => 'Al-Muntaqim',    'ar' => 'الْمُنْتَقِم',    'meaning' => 'The Avenger',                             'reflection' => 'For those who oppressed and never apologised. For those who hurt and never were stopped. Al-Muntaqim sees them too. Justice will arrive — even if it is in the next life.' ],
		[ 'n' => 'Al-\'Afuww',     'ar' => 'الْعَفُوّ',      'meaning' => 'The Pardoner',                            'reflection' => 'Erases entirely. Stronger than forgiveness — it is as if the sin never happened. The du\'a of the last 10 nights of Ramadan is for this: "Allahumma innaka \'afuwwun..."' ],
		[ 'n' => 'Ar-Ra\'uf',      'ar' => 'الرَّؤُوف',      'meaning' => 'The Compassionate',                       'reflection' => 'Tender, gentle compassion. Mercy with softness. The mother who cannot stay angry at the child. Ar-Ra\'uf — and you are the child He cannot stay angry with for long either.' ],
		[ 'n' => 'Malik-ul-Mulk',  'ar' => 'مَالِك الْمُلْك',  'meaning' => 'The Owner of All Sovereignty',           'reflection' => 'Every kingdom He gives, He takes. He raises the one He wills and lowers the one He wills. The throne you sit on is rented. Use it justly.' ],
		[ 'n' => 'Dhul-Jalali wal-Ikram', 'ar' => 'ذُو الْجَلَالِ وَالْإِكْرَام', 'meaning' => 'The Lord of Majesty and Honour', 'reflection' => 'Majesty that demands awe AND honour that gives generously. Both at once. He is the King you fear AND the Father you run to. Hold both.' ],
		[ 'n' => 'Al-Muqsit',      'ar' => 'الْمُقْسِط',      'meaning' => 'The Equitable',                           'reflection' => 'Justice with equity — giving each their due. Not equality, equity. The orphan gets what the orphan needs; the wronged get more. Al-Muqsit settles it correctly.' ],
		[ 'n' => 'Al-Jami\'',      'ar' => 'الْجَامِع',      'meaning' => 'The Gatherer',                            'reflection' => 'He gathers — the believers in Jannah, the wronged with their oppressors at judgement, the scattered limbs at resurrection. Al-Jami\'. Nothing remains scattered forever.' ],
		[ 'n' => 'Al-Ghaniyy',     'ar' => 'الْغَنِيّ',      'meaning' => 'The Self-Sufficient',                     'reflection' => 'Needs nothing from anyone. Your worship does not enrich Him. Your sins do not diminish Him. The transaction is one-way: He needs nothing, you need Him completely.' ],
		[ 'n' => 'Al-Mughni',      'ar' => 'الْمُغْنِي',      'meaning' => 'The Enricher',                            'reflection' => 'And He enriches whom He wills. Wealth — yes. But also iman, peace, family, contentment. Al-Mughni gives the kind of richness no bank statement measures.' ],
		[ 'n' => 'Al-Mani\'',      'ar' => 'الْمَانِع',      'meaning' => 'The Preventer',                           'reflection' => 'He withholds what would harm you. The thing you wanted that He kept from you — He saw what was inside it that would have hurt. Al-Mani\' protects through "no."' ],

		[ 'n' => 'Ad-Darr',        'ar' => 'الضَّارّ',       'meaning' => 'The Distresser',                          'reflection' => 'He allows harm — for purposes only He fully knows. Test, refinement, return. Whatever harm reaches you reaches you by His permission. Sit with that — and ask Him to use it well.' ],
		[ 'n' => 'An-Nafi\'',      'ar' => 'النَّافِع',      'meaning' => 'The Benefiter',                           'reflection' => 'And every benefit comes from Him. The doctor who healed you — through An-Nafi\'. The friend who loved you — sent by An-Nafi\'. Trace every good back to Him.' ],
		[ 'n' => 'An-Nur',         'ar' => 'النُّور',         'meaning' => 'The Light',                               'reflection' => 'Light of the heavens and earth — and of the believer\'s heart. The light by which you see truth from falsehood. An-Nur. Ask Him to put more light in your heart tonight.' ],
		[ 'n' => 'Al-Hadi',        'ar' => 'الْهَادِي',      'meaning' => 'The Guide',                               'reflection' => 'Guidance is His to give, not yours to earn. Every prayer, every page of Quran, every moment of clarity — Al-Hadi opened it. The one He guides cannot be misguided.' ],
		[ 'n' => 'Al-Badi\'',      'ar' => 'الْبَدِيع',      'meaning' => 'The Incomparable',                        'reflection' => 'Originator without imitation. Every snowflake is unique. Every fingerprint is one of a kind. The creativity in creation points to Al-Badi\' — the one whose imagination has no limit.' ],
		[ 'n' => 'Al-Baqi',        'ar' => 'الْبَاقِي',      'meaning' => 'The Everlasting',                         'reflection' => 'Remains when everything else ends. Your loved ones will be lost. Your possessions, your reputation, your body — gone. Al-Baqi remains. Attach yourself to what remains.' ],
		[ 'n' => 'Al-Warith',      'ar' => 'الْوَارِث',      'meaning' => 'The Inheritor',                           'reflection' => 'Everything returns to Him. The wealth you accumulate is given back. The body you cared for returns to dust. Al-Warith inherits it all. Send something ahead while you can.' ],
		[ 'n' => 'Ar-Rashid',      'ar' => 'الرَّشِيد',      'meaning' => 'The Guide to the Right Path',             'reflection' => 'Rightness in every decree. The path He chose for you is correct, even when you cannot see why. Ar-Rashid does not miscalculate. Surrender to His ordering.' ],
		[ 'n' => 'As-Sabur',       'ar' => 'الصَّبُور',      'meaning' => 'The Patient',                             'reflection' => 'His patience with you is endless. The disobedience He sees and does not strike down. The forgetfulness He overlooks. As-Sabur. Learn patience by knowing whose attribute it is.' ],
	];
}
